"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[3722],{63722:a=>{a.exports=JSON.parse('{"slug":"tarify-gaz-elektrichestvo-oktyabr-2026","locale":"ru","title":"Газ подорожал на 9,6%, электричество для населения на 11,3% с 1 октября 2026 года","description":"С 1 октября 2026 года свет для населения подорожал на 11,3%, газ на 9,6%. Из чего состоит квитанция, сколько это в рублях и что будет в июле 2027.","blocks":[{"id":"b001","kind":"paragraph","text":"С 1 октября 2026 года в России подорожали газ и электричество. Оптовая цена газа \xabГазпрома\xbb выросла на 9,6%. Цена электроэнергии для населения выросла на 11,3%, если дом тратит до 3900 кВт\xb7ч в месяц. Цены на газ и свет для населения в России устанавливает не рынок, а государство: по графику и на процент, заложенный в прогноз правительства. Такую цену называют регулируемой. Поэтому повышение на 2026 год было видно ещё год назад в экономическом прогнозе правительства."},{"id":"b002","kind":"paragraph","text":"Квитанция за газ состоит из трёх частей. 80% платы приходится на сам газ, 15% на доставку по трубам до дома и 5% на услуги компании, которая выставляет счёт. С 1 октября каждую часть подняли отдельно: газ на 9,6%, доставку на 11,6%, услуги на 5,1%. Вместе квитанция за газ вырастет примерно на 9,7% (0,8 \xd7 9,6 + 0,15 \xd7 11,6 + 0,05 \xd7 5,1)."},{"id":"b003","kind":"paragraph","text":"С электричеством та же логика: цена для дома складывается из самой энергии и её доставки по проводам. Магистральные сети (ЕНЭС) подняли тариф на 16%, местные распределительные сети на 15,2%. Конечная цена для населения выросла меньше, на 11,3%. Доставка подорожала сильно, но это только часть счёта."},{"id":"b004","kind":"paragraph","text":"В рублях это выглядит так. На каждую 1000 рублей, которую семья платила за свет, теперь приходится 113 рублей прибавки, за газ около 97 рублей. В Москве киловатт-час в квартире с газовой плитой подорожал с 8 до 8,9 рубля. Квартира, которая тратит 200 кВт\xb7ч в месяц, теперь платит 1780 рублей вместо 1600, на 180 рублей больше. Тарифы для населения утверждают местные власти в пределах, которые задала Федеральная антимонопольная служба."},{"id":"b005","kind":"paragraph","text":"Повышение в октябре не последнее. С 1 июля 2027 года газ подорожает ещё на 10,4%, хотя раньше планировали 9,1%. Две индексации подряд поднимут оптовую цену газа примерно на 21% за 9 месяцев (1,096 \xd7 1,104). Тарифы распределительных сетей для населения в июле 2027 года вырастут на 17,5%. Обычно тарифы меняют в июле, и с 2027 года к этому графику вернутся."},{"id":"b006","kind":"paragraph","text":"Для обычного человека выбор такой. Счётчики, экономичные лампы и утепление окупаются быстрее там, где счета большие, например в частном доме с электрическим отоплением. В небольшой квартире такие траты окупаются дольше. Повышение в июле 2027 года можно заложить в семейный бюджет уже сейчас, хотя процент уже раз меняли."},{"id":"b007","kind":"heading","text":"На сколько подорожал газ с 1 октября 2026 года?"},{"id":"b008","kind":"paragraph","text":"Оптовая цена газа выросла на 9,6%, доставка по распределительным сетям на 11,6%, услуги газовых компаний на 5,1%. Вместе квитанция растёт примерно на 9,7%."},{"id":"b009","kind":"heading","text":"На сколько подорожало электричество с 1 октября 2026 года?"},{"id":"b010","kind":"paragraph","text":"Для населения на 11,3% при потреблении до 3900 кВт\xb7ч в месяц. Тарифы сетей выросли сильнее, на 15,2–16%."},{"id":"b011","kind":"heading","text":"Когда следующее повышение тарифов на газ и свет?"},{"id":"b012","kind":"paragraph","text":"С 1 июля 2027 года. Газ подорожает на 10,4%, тарифы распределительных сетей для населения на 17,5%, а это только часть цены света."}],"sources":[{"label":"Регулируемые цены на газ \xabГазпрома\xbb индексируются на 9,6%","url":"https://www.interfax.ru/business/1119546"},{"label":"ФАС России проиндексирует тарифы на природный газ на 9,6% с 1 октября","url":"https://www.garant.ru/news/1947004/"},{"label":"Тариф электросетей в РФ с октября вырос на 15,2%, единой энергосети на 16%","url":"https://www.interfax.ru/russia/1119539"},{"label":"ФАС проверит тарифы на электроэнергию в регионах","url":"https://www.kommersant.ru/doc/8990884"},{"label":"Тарифы на электроэнергию в Москве в 2026 году","url":"https://t-j.ru/msk-electroprices/"},{"label":"Тарифы на электроэнергию в Москве 2026","url":"https://www.vesti.ru/vj/tarify-na-ehlektroehnergiyu-v-moskve"}],"sourceBodySha256":"b809a176f95ae120cd852b989f922de8a276fc4ea55fc40cff70d0caebfcadd4"}')}}]);